/**
 * @distilled.cloud/notion — Notion SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * document mirrored at `specs/spec-mirror-notion/specs/openapi.json`).
 * Everything else in this folder is hand-written.
 *
 * One module per Notion API tag: `pages`, `blocks`, `dataSources`,
 * `databases`, `search`, `users`, `comments`, `fileUploads`, `views`, … The
 * OAuth token endpoints (`/v1/oauth/*`) are not included: they use HTTP
 * Basic client credentials instead of the bearer token.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Notion from "@distilled.cloud/notion";
 *
 * const program = Effect.gen(function* () {
 *   const { results } = yield* Notion.search.searchByTitle({ query: "Roadmap", page_size: 1 });
 *   const first = results[0];
 *   if (first === undefined || first.object !== "page") return undefined;
 *   return yield* Notion.pages.getPage({ page_id: first.id });
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Notion.CredentialsFromEnv,
 *   Notion.NotionProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { NotionProtocol, type NotionOpError, type NotionOpContext } from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
